mapper.select:
SELECT i.id, i.material_id, i.location_id, l.location_code, i.container_code, i.batch_no, i.quantity, i.locked_qty, i.ownership_type, i.create_time FROM wms_inventory i JOIN wms_location l ON l.id = i.location_id AND l.deleted_at = 0 JOIN wms_warehouse w ON w.id = l.warehouse_id AND w.deleted_at = 0 WHERE i.material_id = #{materialId} AND w.warehouse_type = #{warehouseType} AND i.ownership_type = 'OWNED' AND i.quantity - i.locked_qty > 0
AND i.batch_no = #{batchNo}
AND i.container_code <> ''
ORDER BY i.create_time ASC, i.container_code ASC, i.id ASC LIMIT #{limit}

SELECT i.id, i.material_id, i.location_id, l.location_code, i.container_code, i.batch_no, i.quantity, i.locked_qty, i.ownership_type, i.create_time FROM wms_inventory i JOIN wms_location l ON l.id = i.location_id AND l.deleted_at = 0 JOIN wms_warehouse w ON w.id = l.warehouse_id AND w.deleted_at = 0 WHERE i.material_id = #{materialId} AND w.id = #{warehouseId} AND i.ownership_type = 'OWNED'
AND i.container_code = #{containerCode}
AND i.quantity - i.locked_qty > 0
AND i.batch_no = #{batchNo}
AND i.container_code <> ''
ORDER BY i.create_time ASC, i.container_code ASC, i.id ASC LIMIT #{limit}

mapper.update:
UPDATE wms_inventory
   SET locked_qty = locked_qty + #{qty},
       update_time = NOW()
 WHERE id = #{id}
   AND quantity - locked_qty >= #{qty}

UPDATE wms_inventory
   SET locked_qty = locked_qty - #{qty},
       update_time = NOW()
 WHERE id = #{id}
   AND locked_qty >= #{qty}

UPDATE wms_inventory
   SET quantity = quantity - #{qty},
       locked_qty = locked_qty - #{qty},
       update_time = NOW()
 WHERE id = #{id}
   AND locked_qty >= #{qty}
   AND quantity >= #{qty}

UPDATE wms_inventory
   SET quantity = quantity - #{qty},
       update_time = NOW()
 WHERE id = #{id}
   AND quantity >= #{qty}

UPDATE wms_inventory
   SET quantity = #{qty},
       update_time = NOW(),
       update_by = #{updateBy}
 WHERE id = #{id}
